import type { ToolDefinition } from './types'

export type WhmLayout = 'form' | 'wizard' | 'table' | 'confirm' | 'status' | 'restart' | 'account-action' | 'settings'

export interface WhmField {
	name: string
	label: string
	type: 'text' | 'password' | 'number' | 'select' | 'textarea' | 'checkbox' | 'account' | 'package'
	options?: Array<{ value: string; label: string }>
	required?: boolean
	help?: string
	defaultValue?: string
}

export interface WhmFeature {
	id: string
	label: string
	description: string
	category: string
	icon: string
	layout: WhmLayout
	path: string
	capabilities: string[]
	matchAll?: boolean
	dedicated?: boolean
	steps: string[]
	fields?: WhmField[]
	settingKey?: string
	related?: string[]
	accountAction?: 'patch' | 'suspend' | 'unsuspend' | 'password' | 'terminate' | 'impersonate' | 'service-restart'
}

function feature (entry: WhmFeature): WhmFeature {
	return entry
}

