export function featureById (id: string): WhmFeature | undefined {
	return whmFeatures.find((entry) => entry.id === id)
}

export function featureByPath (pathname: string, search = ''): WhmFeature | undefined {
	const path = `${pathname}${search}`
	return whmFeatures.find((entry) => entry.path === path) || whmFeatures.find((entry) => entry.path === pathname)
}

export function toToolDefinition (feature: WhmFeature): ToolDefinition {
	return {
		id: feature.id,
		label: feature.label,
		description: feature.description,
		category: feature.category,
		path: feature.path,
		icon: feature.icon,
		capabilities: feature.capabilities,
		matchAll: feature.matchAll,
	}
}
